/** Fase Palmerton + método de una fila (por su d). */
export function fasePalmertonDe(d: number): FaseFila | undefined { return FASE_FILA[d]; }
export function faseInfo(id: string): FasePalmerton | undefined { return FASES_PALMERTON.find((f) => f.id === id); }
/** Textos de los ajustes de una fila (vacío = la fila ya cumple su fase). */
export function ajustesDe(d: number): string[] { const x = FASE_FILA[d]; return x ? x.ajustes.map((k) => AJUSTES_PALMERTON[k]).filter(Boolean) : []; }
export function notaDe(d: number): string | undefined { const x = FASE_FILA[d]; return x && x.nota ? NOTAS_PALMERTON[x.nota] : undefined; }
export function metodoSistemaDe(key: string | null | undefined): MetodoSistema | undefined { return key ? METODO_SISTEMA[key] : undefined; }
